public class Main {
    public static void main(String[] args) {
        String applicant = "Sarah Jenkins";
        int age = 29;
        double annualIncome = 85000.0;
        String employment = "EMPLOYED";
        double dtiRatio = 28.5;
        int creditScore = 760;
        String loanType = "AUTO";

        // Phase 1: Eligibility Guard Clauses
        if (age < 21 || age > 65 || annualIncome < 30000.0 ||
            (!"EMPLOYED".equals(employment) && !"SELF_EMPLOYED".equals(employment)) ||
            dtiRatio >= 45.0 || creditScore < 580) {
            System.out.println("=== Loan Underwriting Report ===");
            System.out.println("Applicant: " + applicant);
            System.out.println("Eligibility: REJECTED");
            return;
        }

        // Phase 2: Risk Tier Assignment
        int tier;
        String tierName;
        double riskPremium;
        if (creditScore >= 750) {
            tier = 1;
            tierName = "Tier 1 (Prime)";
            riskPremium = 0.0;
        } else if (creditScore >= 670) {
            tier = 2;
            tierName = "Tier 2 (Near Prime)";
            riskPremium = 1.5;
        } else {
            tier = 3;
            tierName = "Tier 3 (Subprime)";
            riskPremium = 3.5;
        }

        // Phase 3: Base Rate Assignment via Modern Switch Expression
        double baseRate = switch (loanType) {
            case "MORTGAGE" -> 6.5;
            case "AUTO" -> 7.5;
            case "PERSONAL" -> 11.0;
            default -> 12.0;
        };

        double finalRate = baseRate + riskPremium;
        int maxAmount = (int) (annualIncome * (tier == 1 ? 0.6 : (tier == 2 ? 0.4 : 0.25)));

        System.out.println("=== Loan Underwriting Report ===");
        System.out.println("Applicant: " + applicant);
        System.out.println("Eligibility: APPROVED");
        System.out.println("Risk Rating: " + tierName);
        System.out.println("Loan Type: " + loanType);
        System.out.println("Base Rate: " + baseRate + "%");
        System.out.printf("Final Approved Rate: %.2f%%%n", finalRate);
        System.out.println("Max Approved Amount: $" + maxAmount);
    }
}

